<template>
  <main class="editor-page" v-loading="loading">
    <header class="editor-header"><div><router-link to="/admin/questions">← 题库工作台</router-link><h1>{{ recordId?'编辑题目':'自行出题' }}</h1><p>{{ state.published_version?`当前已发布 v${state.published_version} · 正在编辑草稿`:'从空白题目开始，或在题库中复制已有题目。' }}</p></div><div class="editor-actions"><span :class="{unsaved:dirty}">{{ dirty?'有未保存修改':savedText }}</span><el-button v-if="recordId" @click="openVersions">历史版本</el-button><el-button @click="preview" :disabled="busy">学生视角预览</el-button><el-button class="save-draft-button" @click="save" :loading="busy">保存草稿</el-button><el-button type="primary" @click="publish" :disabled="busy">发布题目</el-button></div></header>
    <p v-if="notice" class="notice" role="alert">{{ notice }}</p>
    <fieldset class="editor-fields" :disabled="loading||busy"><div class="editor-grid">
      <div class="editor-main">
        <section class="editor-panel"><div class="panel-title"><h2>题目内容</h2><span>原图站场 · 自主编排</span></div>
          <label class="control">题目标题<el-input v-model="form.title" maxlength="150" placeholder="如：D13至II股道的带动道岔分析" aria-label="题目标题"/></label>
          <div class="control-grid"><label class="control">所属专题<el-select v-model="form.topic" aria-label="所属专题"><el-option v-for="t in topics" :key="t.id" :value="t.id" :label="t.title"/></el-select></label><label class="control">难度<el-select v-model="form.level" allow-create filterable aria-label="难度"><el-option v-for="l in ['基础','综合','分析']" :key="l" :label="l" :value="l"/></el-select></label><label class="control">专题内排序<el-input-number v-model="form.sequence" :min="1" :max="999" aria-label="专题内排序"/></label></div>
          <label class="control">题干<el-input v-model="form.prompt" type="textarea" :rows="5" maxlength="6000" show-word-limit placeholder="说明任务、已知条件和学生需要完成的工作。" aria-label="题干"/></label>
          <label class="control">题设条件（每行一条）<el-input :model-value="form.conditions.join('\n')" @update:model-value="v=>form.conditions=lines(v)" type="textarea" :rows="3" placeholder="如：进路内区段空闲，道岔有表示。" aria-label="题设条件"/></label>
          <div class="control-grid two"><label class="control">图示背景<el-select v-model="form.diagram_mode" aria-label="图示背景"><el-option label="原图站场" value="station"/><el-option label="原图站场＋半自动闭塞题设" value="semi_auto"/><el-option label="原图站场＋自动闭塞题设" value="auto"/></el-select></label><label class="control">标签（以逗号分隔）<el-input :model-value="form.tags.join('，')" @update:model-value="v=>form.tags=v.split(/[，,]/).map(x=>x.trim()).filter(Boolean)" aria-label="标签"/></label></div>
          <label class="control">命题与评分依据<el-input v-model="form.source_section" type="textarea" :rows="2" maxlength="1500" placeholder="填写对应实验报告位置，或自编题所依据的资料。" aria-label="命题依据"/></label>
          <details class="extra-settings"><summary>关联站场设备（便于记录题目涉及的设备）</summary><el-select v-model="form.devices" multiple filterable placeholder="选择原图设备" aria-label="关联设备"><el-option v-for="d in devices" :key="d" :label="d" :value="d"/></el-select></details>
        </section>
        <section class="fields-heading"><div><h2>答题栏与评分规则</h2><p>可组合多种题型；每个答题栏单独设置分值和解析。</p></div><el-dropdown trigger="click" @command="addField"><el-button type="primary" plain>＋ 添加答题栏</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="(label,kind) in kinds" :key="kind" :command="kind">{{ label }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></section>
        <el-empty v-if="!form.fields.length" description="添加第一个答题栏"/>
        <article v-for="(field,index) in form.fields" :key="field.id" :id="`edit-${field.id}`" class="field-card" :class="{'is-expanded':activeField===field.id}">
          <header class="field-bar"><button class="field-toggle" :aria-expanded="activeField===field.id" :aria-controls="`edit-body-${field.id}`" @click="activeField=activeField===field.id?'':field.id"><span>{{ String(index+1).padStart(2,'0') }}</span><strong>{{ field.label||'未命名答题栏' }}</strong><small>{{ kinds[field.kind] }} · {{ field.points }}分</small><span class="field-chevron" aria-hidden="true">{{ activeField===field.id?'⌃':'⌄' }}</span></button><div class="field-tools"><button :disabled="index===0" @click="moveField(index,-1)" title="上移答题栏" aria-label="上移答题栏">↑</button><button :disabled="index===form.fields.length-1" @click="moveField(index,1)" title="下移答题栏" aria-label="下移答题栏">↓</button><button @click="duplicateField(index)">复制</button><button class="remove-field" @click="removeField(index)">移除</button></div></header>
          <div v-show="activeField===field.id" class="field-body" :id="`edit-body-${field.id}`">
            <div class="control-grid two"><label class="control">题型<el-select :model-value="field.kind" @update:model-value="v=>changeKind(index,v)" aria-label="答题栏题型"><el-option v-for="(label,kind) in kinds" :key="kind" :value="kind" :label="label"/></el-select></label><label class="control">本栏分值<el-input-number v-model="field.points" :min="1" :max="100" :precision="0" aria-label="本栏分值"/></label></div>
            <label class="control">本栏问题<el-input v-model="field.label" type="textarea" :rows="2" maxlength="1000" aria-label="本栏问题"/></label>
            <template v-if="['choice','multi','order'].includes(field.kind)">
              <div class="option-caption"><strong>选项</strong><small>{{ field.kind==='order'?'选项展示顺序与正确顺序分开设置。':'点击“答案”选择正确项，选项内容可直接编辑。' }}</small></div>
              <div v-for="(option,i) in field.options" :key="i" class="option-editor"><label v-if="field.kind==='choice'" class="correct-toggle"><input type="radio" :name="`correct-${field.id}`" :value="option" v-model="field.expected" :aria-label="`选项${i+1}为正确答案`"><span>答案</span></label><label v-else-if="field.kind==='multi'" class="correct-toggle"><input type="checkbox" :value="option" v-model="field.expected" :aria-label="`选项${i+1}为正确答案`"><span>答案</span></label><span v-else>{{ i+1 }}</span><el-input :model-value="option" @update:model-value="v=>renameOption(field,i,v)" :aria-label="`选项${i+1}`"/><button @click="removeOption(field,i)" title="移除选项" :aria-label="`移除选项${i+1}`">×</button></div>
              <el-button size="small" :disabled="field.options.length>=20" @click="field.options.push(`选项${field.options.length+1}`)">＋ 添加选项</el-button>
              <label v-if="field.kind==='multi'" class="control">多选评分方式<el-select v-model="field.scoring" aria-label="多选评分方式"><el-option label="全部选对得分，否则0分" value="exact"/><el-option label="少选按正确选项比例得分，错选0分" value="partial"/></el-select></label>
              <div v-if="field.kind==='order'" class="correct-order"><strong>正确顺序</strong><p v-for="(option,i) in field.expected" :key="i"><span>{{ i+1 }}. {{ option }}</span><button :disabled="i===0" @click="moveOption(field,i,-1)">↑</button><button :disabled="i===field.expected.length-1" @click="moveOption(field,i,1)">↓</button></p><el-button size="small" @click="field.expected=[...field.options]">按当前选项重置正确顺序</el-button></div>
            </template>
            <template v-if="field.kind==='cell'"><label class="control">参考填写<el-input v-model="field.expected" type="textarea" :rows="2" aria-label="参考填写"/></label><p class="notation-sample">排版预览：<Notation :text="field.expected"/></p><div class="control-grid two"><label class="control">比对方式<el-select v-model="field.matching" aria-label="比对方式"><el-option label="设备集合：忽略排列顺序" value="tokens"/><el-option label="顺序填写：逐项顺序一致" value="ordered"/><el-option label="完整文本：仅忽略首尾空格" value="text"/></el-select></label><label class="control">其他可接受答案（每行一个完整答案）<el-input :model-value="(field.accepted_answers||[]).join('\n')" @update:model-value="v=>field.accepted_answers=lines(v)" type="textarea" :rows="2" aria-label="其他可接受答案"/></label></div><p class="hint">设备填写保留（反位）、[防护]、{带动}和&lt;条件&gt;。修改原表参考答案或比对规则后，此栏按管理员自定答案评分。</p></template>
            <template v-if="field.kind==='essay'"><label class="control">评分要点（每行一条）<el-input :model-value="field.criteria.join('\n')" @update:model-value="v=>field.criteria=lines(v)" type="textarea" :rows="3" aria-label="评分要点"/></label><div class="rubric-title"><strong>分项评分细则</strong><span :class="{invalid:rubricTotal(field)!==field.points&&field.rubric.length}">{{ rubricTotal(field) }} / {{ field.points }} 分</span></div><p class="hint">启用后，批阅时按细则给分并自动合计；不设细则时可直接填写本栏总分。</p><div v-for="(r,i) in field.rubric" :key="r.id" class="rubric-row"><el-input v-model="r.label" placeholder="如：正确区分占用与锁闭" :aria-label="`评分细则${i+1}`"/><el-input-number v-model="r.points" :min="1" :max="100" :precision="0" :aria-label="`细则${i+1}分值`"/><button :aria-label="`移除评分细则${i+1}`" @click="field.rubric.splice(i,1)">×</button></div><div class="rubric-actions"><el-button size="small" :disabled="field.rubric.length>=15" @click="addRubric(field)">＋ 添加细则</el-button><el-button v-if="field.criteria.length&&!field.rubric.length" size="small" @click="fromCriteria(field)">将要点拆分为细则</el-button><el-button v-if="field.rubric.length" size="small" @click="distribute(field)">平均分配本栏分值</el-button></div></template>
            <label class="control">{{ field.kind==='essay'?'参考答案与解析（明确有据结论和待核实内容）':'答案解析与纠正建议' }}<el-input v-model="field.explanation" type="textarea" :rows="field.kind==='essay'?7:3" maxlength="6000" :placeholder="field.kind==='essay'?'填写有资料支持的参考解答，注明仍需实测或资料核实的部分。':'解释为什么这样填写；说明常见错误及纠正方法。'" :aria-label="field.kind==='essay'?'参考答案与解析':'答案解析'"/></label>
          </div>
        </article>
      </div>
      <aside class="editor-side"><section class="editor-panel"><h2>题目结构</h2><div class="score-total">{{ totalPoints }}<small> 分</small></div><p class="hint">{{ form.fields.length }} 个作答栏<br>自动核对 {{ autoPoints }} 分 · 人工评阅 {{ totalPoints-autoPoints }} 分</p><nav class="field-index"><button v-for="(f,i) in form.fields" :key="f.id" @click="jumpField(f.id)" :aria-current="activeField===f.id?'true':undefined"><span>{{ i+1 }}</span>{{ f.label||kinds[f.kind] }}</button></nav><p class="hint">保存草稿：仅后台可见修改。<br>发布题目：新作答使用新版本，已提交记录保留原题。</p></section></aside>
    </div></fieldset>
    <el-drawer v-model="previewOpen" title="学生视角预览与试答" size="min(1050px, 96vw)" destroy-on-close><QuestionPreview v-if="previewData" :question="previewData" :content="previewContent"/></el-drawer>
    <el-drawer v-model="versionsOpen" title="已发布版本" size="min(520px, 95vw)"><el-empty v-if="!versions.length" description="保存并发布后建立第一个版本"/><article v-for="v in versions" :key="v.version" class="version-card"><h3>v{{ v.version }} · <Notation :text="v.title"/></h3><p>{{ v.note }}</p><small>{{ formatDate(v.created_at) }}</small><el-button @click="restore(v)" :disabled="busy">载入为编辑草稿</el-button></article><p class="hint">载入历史版本不会立即影响学生；检查后需要再次发布。</p></el-drawer>
  </main>
</template>

<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import Notation from '@/components/RailwayNotation.vue'
import QuestionPreview from '@/components/QuestionPreview.vue'
import {getManagementMetadata,getManagedQuestion,createManagedQuestion,saveQuestionDraft,publishQuestion,previewManagedQuestion,getQuestionVersions,restoreQuestionVersion} from '@/api/management'
const route=useRoute(),router=useRouter(),loading=ref(true),busy=ref(false),recordId=ref(null),state=ref({revision:0,published_version:0}),dirty=ref(false),savedText=ref('尚未保存'),notice=ref('')
const topics=ref([]),devices=ref([]),activeField=ref(''),previewOpen=ref(false),previewData=ref(null),previewContent=ref(null),versionsOpen=ref(false),versions=ref([])
const kinds={choice:'单选 / 判断',multi:'多项选择',order:'时序排序',cell:'填写题',essay:'论述 / 记录'}
const clone=value=>JSON.parse(JSON.stringify(value)),uid=()=>`f_${crypto.randomUUID().replaceAll('-','').slice(0,12)}`
function newField(kind){const f={id:uid(),kind,label:'',points:10};if(kind==='essay')Object.assign(f,{criteria:[],rubric:[]});else{f.explanation='';if(kind==='cell')Object.assign(f,{expected:'',accepted_answers:[],matching:'tokens'});else Object.assign(f,{options:['选项1','选项2'],expected:kind==='choice'?'':kind==='order'?['选项1','选项2']:[],scoring:'exact'})}return f}
const form=ref({title:'未命名题目',topic:9,sequence:1,level:'基础',prompt:'',conditions:[],source_section:'管理员命题',tags:[],devices:[],diagram_mode:'station',fields:[newField('essay')]})
const totalPoints=computed(()=>form.value.fields.reduce((s,f)=>s+(Number(f.points)||0),0)),autoPoints=computed(()=>form.value.fields.filter(f=>f.kind!=='essay').reduce((s,f)=>s+(Number(f.points)||0),0))
let initializing=false,localKey=''
const lines=value=>value.split('\n')
function prepared(){const value=clone(form.value);value.conditions=value.conditions.map(x=>x.trim()).filter(Boolean);for(const f of value.fields){if(f.criteria)f.criteria=f.criteria.map(x=>x.trim()).filter(Boolean);if(f.accepted_answers)f.accepted_answers=f.accepted_answers.map(x=>x.trim()).filter(Boolean)}return value}
function normalize(value){const result=clone(value);result.tags??=[];result.devices??=[];result.diagram_mode??=result.topic===7?'semi_auto':result.topic===8?'auto':'station';for(const f of result.fields){if(f.kind==='essay'){f.criteria??=[];f.rubric??=[]}if(f.kind==='cell'){f.accepted_answers??=[];f.matching??=f.binding?.column==='排列进路按下按钮'?'ordered':'tokens'}if(f.kind==='multi')f.scoring??='exact'}return result}
function draftKey(){return `srtp_editor_${JSON.parse(localStorage.getItem('railway_user')||'{}').id}_${recordId.value||'new'}`}
watch(form,()=>{if(initializing)return;dirty.value=true;try{localStorage.setItem(draftKey(),JSON.stringify({revision:state.value.revision,content:form.value}))}catch{}},{deep:true,flush:'sync'})
function adopt(data){initializing=true;state.value=data;recordId.value=data.id;form.value=normalize(data.content);activeField.value=form.value.fields[0]?.id||'';dirty.value=false;savedText.value='草稿已保存';initializing=false}
async function load(){loading.value=true;notice.value='';try{if(route.params.id){adopt(await getManagedQuestion(route.params.id))}else activeField.value=form.value.fields[0]?.id||'';localKey=draftKey();let draft=null;try{draft=JSON.parse(localStorage.getItem(localKey))}catch{};if(draft&&draft.revision===state.value.revision){try{await ElMessageBox.confirm('发现本机未保存的编辑内容，是否恢复？','恢复编辑',{confirmButtonText:'恢复',cancelButtonText:'使用后台内容'});initializing=true;form.value=normalize(draft.content);initializing=false;dirty.value=true}catch{localStorage.removeItem(localKey)}}}finally{loading.value=false}}
async function save(){if(busy.value)return false;busy.value=true;notice.value='';try{const previousKey=draftKey();const data=recordId.value?await saveQuestionDraft(recordId.value,prepared(),state.value.revision):await createManagedQuestion(prepared());adopt(data);localStorage.removeItem(previousKey);localStorage.removeItem(draftKey());if(!route.params.id)await router.replace(`/admin/questions/${data.id}`);return true}catch(e){notice.value=detail(e,'保存失败，编辑内容已保留。');return false}finally{busy.value=false}}
async function publish(){if(!(await save()))return;try{await ElMessageBox.confirm('发布后学生的新作答将使用此版本；旧作答保留原题与原评分依据。','发布题目',{confirmButtonText:'发布',cancelButtonText:'继续编辑'})}catch{return}busy.value=true;try{state.value={...state.value,...await publishQuestion(recordId.value,state.value.revision,'管理员网页编辑发布')};savedText.value=`已发布 v${state.value.published_version}`;dirty.value=false;ElMessage.success('题目已发布，学生可在实验专题中作答')}catch(e){notice.value=detail(e,'发布失败，请检查题目和评分规则。')}finally{busy.value=false}}
async function preview(){busy.value=true;notice.value='';try{previewContent.value=prepared();previewData.value=(await previewManagedQuestion(previewContent.value)).question;previewOpen.value=true}catch(e){notice.value=detail(e,'请先补全题干、答案与评分规则。')}finally{busy.value=false}}
function detail(e,fallback){return typeof e.response?.data?.detail==='string'?e.response.data.detail:fallback}
function addField(kind){const f=newField(kind);form.value.fields.push(f);activeField.value=f.id;nextTick(()=>jumpField(f.id))}
function changeKind(i,kind){const old=form.value.fields[i];form.value.fields[i]={...newField(kind),id:old.id,label:old.label,points:old.points}}
function moveField(i,d){const a=form.value.fields;[a[i],a[i+d]]=[a[i+d],a[i]]}
function duplicateField(i){const f=clone(form.value.fields[i]);f.id=uid();form.value.fields.splice(i+1,0,f);activeField.value=f.id}
async function removeField(i){const f=form.value.fields[i];if(f.label||f.expected||f.criteria?.length){try{await ElMessageBox.confirm(`从草稿移除“${f.label||'此答题栏'}”？`,'移除答题栏',{confirmButtonText:'移除',cancelButtonText:'取消'})}catch{return}}form.value.fields.splice(i,1)}
function renameOption(f,i,v){const old=f.options[i];f.options[i]=v;if(Array.isArray(f.expected))f.expected=f.expected.map(x=>x===old?v:x);else if(f.expected===old)f.expected=v}
function removeOption(f,i){const old=f.options.splice(i,1)[0];if(Array.isArray(f.expected))f.expected=f.expected.filter(x=>x!==old);else if(f.expected===old)f.expected=''}
function moveOption(f,i,d){[f.expected[i],f.expected[i+d]]=[f.expected[i+d],f.expected[i]]}
function rubricTotal(f){return f.rubric.reduce((s,r)=>s+(Number(r.points)||0),0)}
function addRubric(f){f.rubric.push({id:uid(),label:'',points:Math.max(1,f.points-rubricTotal(f))})}
function distribute(f){if(f.rubric.length>f.points){ElMessage.warning('每项细则至少1分，请提高本栏分值或减少细则。');return}f.rubric.forEach((r,i)=>r.points=Math.floor(f.points/f.rubric.length)+(i<f.points%f.rubric.length?1:0))}
function fromCriteria(f){if(f.criteria.length>15||f.criteria.length>f.points){ElMessage.warning('评分要点数量须不超过15且不超过本栏分值。');return}f.rubric=f.criteria.map(label=>({id:uid(),label,points:1}));distribute(f)}
function jumpField(id){activeField.value=id;nextTick(()=>document.getElementById(`edit-${id}`)?.scrollIntoView({behavior:'smooth',block:'start'}))}
async function openVersions(){versions.value=await getQuestionVersions(recordId.value);versionsOpen.value=true}
async function restore(v){if(dirty.value){try{await ElMessageBox.confirm('载入历史版本会替换当前未保存的编辑内容。','载入草稿',{confirmButtonText:'载入',cancelButtonText:'取消'})}catch{return}}busy.value=true;try{adopt(await restoreQuestionVersion(recordId.value,v.version,state.value.revision));localStorage.removeItem(draftKey());versionsOpen.value=false;ElMessage.success('历史版本已载入草稿，尚未发布')}finally{busy.value=false}}
function formatDate(v){return new Date(v.endsWith('Z')?v:v+'Z').toLocaleString('zh-CN')}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>{if(!dirty.value)return true;try{await ElMessageBox.confirm('编辑尚未保存到后台。本机已保留草稿，确定离开？','尚未保存',{confirmButtonText:'离开',cancelButtonText:'继续编辑'});return true}catch{return false}})
watch(()=>route.params.id,id=>{if(String(id||'')!==String(recordId.value||''))load()})
onMounted(async()=>{const meta=await getManagementMetadata();topics.value=meta.topics;const t=meta.topology;devices.value=t?[...t.signals.map(s=>s.name),...t.switches.map(s=>s.id),...t.sections.map(s=>s.name)]:[];await load();window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>

<style scoped>
.editor-fields{border:0;margin:0;padding:0;min-width:0}
